window.RP_SESSION={"id":"S-6aa180b94989","messages":[{"id":"RP-III-0009392","time":"2026-01-24T10:36:00+09:00","room":"RP III","name":"릴리스 레이샤","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“아름다움이란 뭘까..”\n\n이른 새벽. 모험가가 되기위해 길드에 왔지만 아직 정식 길드원이 아닌 신병 릴리스는 무덤 근처에 앉아 혼자만의 세계에 갇혀 많은 생각을 하고 있었다.","characters":["P-f6914530ed3f"]},{"id":"RP-III-0009393","time":"2026-01-24T10:37:00+09:00","room":"RP III","name":"릴리스 레이샤","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“저 꽃은 아름다운 것.”\n\n릴리스가 바라보는 곳에는 축 쳐졌지만 강렬한 보라색을 가지고 있는 아름다운 꽃이 보였다.","characters":["P-f6914530ed3f"]},{"id":"RP-III-0009394","time":"2026-01-24T10:39:00+09:00","room":"RP III","name":"릴리스 레이샤","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“사슴의 뿔도 아름답고, 황금도 아름다워.“","characters":["P-f6914530ed3f"]},{"id":"RP-III-0009395","time":"2026-01-24T10:40:00+09:00","room":"RP III","name":"릴리스 레이샤","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“귀족도 아름다운데, 나는 아름다운가?”\n\n골똘…","characters":["P-f6914530ed3f"]},{"id":"RP-III-0009396","time":"2026-01-24T10:42:00+09:00","room":"RP III","name":"릴리스 레이샤","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“모르겠어.”\n\n이내 릴리스는 드레스에 묻은 더러운 흙을 털어버리고는 자리에서 일어나 길드로 향했다.","characters":["P-f6914530ed3f"]},{"id":"RP-III-0009397","time":"2026-01-24T10:48:00+09:00","room":"RP III","name":"릴리스 레이샤","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"길드로 가던중에 유리로 만들어진 창문을 발견한 릴리스.\n\n“유리도 아름답네..”","characters":["P-f6914530ed3f"]},{"id":"RP-III-0009398","time":"2026-01-24T10:48:00+09:00","room":"RP III","name":"릴리스 레이샤","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“ …. “","characters":["P-f6914530ed3f"]},{"id":"RP-III-0009399","time":"2026-01-24T10:49:00+09:00","room":"RP III","name":"릴리스 레이샤","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"하- 호- \n\n입김을 불어 창문에 뿌연 막을 형성시켰다. 그리고는 릴리스는 그림을 그렸다. 용사 클램시와 사악한 용 크아킨의 전투! \n\n잘 그린 탓인지 사람들이 몰렸고, 아이들이 감탄했고, 화내야할 집 주인마저 미소를 보였다.","characters":["P-f6914530ed3f"]},{"id":"RP-III-0009400","time":"2026-01-24T10:51:00+09:00","room":"RP III","name":"릴리스 레이샤","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“ 나 이런것도 할 줄 아네. 나 아름답구나…”","characters":["P-f6914530ed3f"]},{"id":"RP-III-0009401","time":"2026-01-24T10:51:00+09:00","room":"RP III","name":"릴리스 레이샤","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-f6914530ed3f"]},{"id":"RP-III-0009402","time":"2026-01-24T10:51:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]}]};
